sparql.by_label:
SELECT ?name ?item ?title (GROUP_CONCAT(DISTINCT ?tl;separator="|") AS ?inst) (GROUP_CONCAT(DISTINCT ?pl;separator="|") AS ?prods) (GROUP_CONCAT(DISTINCT ?il;separator="|") AS ?inds) WHERE {
 VALUES ?name { "Michael Kors"@en "Longchamp"@en "Marc Jacobs"@en "Cuyana"@en "Guess"@en "Coccinelle"@en "Mulberry"@en "Celine"@en "Tory Burch"@en "Stuart Weitzman"@en "Mansur Gavriel"@en "Kate Spade"@en "Brahmin"@en "Zara"@en "Mango"@en "The Row"@en "Staud"@en "Senreve"@en "JW Pei"@en "Dagne Dover"@en "Clare V."@en "Polène"@en "DeMellier"@en "Strathberry"@en "Fossil"@en }
 { ?item rdfs:label ?name } UNION { ?item skos:altLabel ?name }
 ?article schema:about ?item ; schema:isPartOf <https://en.wikipedia.org/> ; schema:name ?title .
 ?item wdt:P31 ?t . FILTER(?t NOT IN (wd:Q5, wd:Q4167410, wd:Q101352, wd:Q202444, wd:Q484170, wd:Q16521, wd:Q11424, wd:Q482994, wd:Q7366, wd:Q134556, wd:Q105543609))
 ?t rdfs:label ?tl . FILTER(LANG(?tl)="en")
 OPTIONAL { ?item wdt:P1056 ?p . ?p rdfs:label ?pl . FILTER(LANG(?pl)="en") }
 OPTIONAL { ?item wdt:P452 ?i . ?i rdfs:label ?il . FILTER(LANG(?il)="en") }
} GROUP BY ?name ?item ?title
